<script setup lang="ts">
import type { DownloadPolicy } from '../../api/contracts/v2/policies'
const props = defineProps<{ modelValue: DownloadPolicy }>()
const emit = defineEmits<{ 'update:modelValue': [value: Partial<DownloadPolicy>]; schedules: [] }>()
</script>
<template><section class="settings-card"><h2>自动化</h2><label class="settings-check"><input type="checkbox" :checked="props.modelValue.idleDownload.enabled" @change="emit('update:modelValue', { idleDownload: { ...props.modelValue.idleDownload, enabled: ($event.target as HTMLInputElement).checked } })" />空闲时自动下载</label><label v-if="props.modelValue.idleDownload.enabled">空闲阈值（秒）<input type="number" min="60" :value="props.modelValue.idleDownload.idleAfterSeconds" @input="emit('update:modelValue', { idleDownload: { ...props.modelValue.idleDownload, idleAfterSeconds: Number(($event.target as HTMLInputElement).value) } })" /></label><label>完成后动作<select :value="props.modelValue.completionAction" @change="emit('update:modelValue', { completionAction: ($event.target as HTMLSelectElement).value as DownloadPolicy['completionAction'] })"><option value="none">无</option><option value="pause-all">暂停全部任务</option><option value="stop-engine">停止引擎</option><option value="suspend">睡眠</option><option value="poweroff">关机</option></select></label><button class="secondary-button" @click="emit('schedules')">管理计划任务</button></section></template>
